"""Travelling waves, initial data, finite boundaries, and classification."""
def populate(add, C, M, table):
    add(13, 'D’Alembert 해법 · 이동하는 좌표로 바꾸는 이유', [
      C('변수분리와 같은 PDE를 다른 좌표로 봅니다.', '원본은 uₜₜ=c²uₓₓ, 양 끝 고정, 초기변위 f와 초기속도 g를 다시 제시합니다. 우선 PDE 자체의 일반적인 진행파 해를 구한 뒤 초기조건을 맞추고, 16쪽에서 고정단 경계조건을 적용합니다.', M(r"v=x+ct,\qquad w=x-ct,\qquad u(x,t)=U(v,w)"), 'c&gt;0이면 x=(v+w)/2, t=(v−w)/(2c)로 되돌릴 수 있으므로 유효한 change of variables(변수변환)입니다.'),
      C('Chain rule(연쇄법칙)로 두 번 미분합니다.', M(r"u_x=U_v+U_w,\qquad u_t=cU_v-cU_w"), M(r"\begin{aligned}u_{xx}&=U_{vv}+2U_{vw}+U_{ww},\\u_{tt}&=c^2U_{vv}-2c^2U_{vw}+c^2U_{ww},\\u_{tt}-c^2u_{xx}&=-4c^2U_{vw}=0.\end{aligned}"), '여기서는 혼합미분 순서를 바꿀 만큼 매끄러운 해를 다룹니다. 두 제곱미분 항이 상쇄되고 Uᵥw=0만 남으므로 좌표 선택이 계산을 크게 단순화합니다.'),
      C('왜 x±ct인가?', '일정한 형태가 속도 c로 오른쪽으로 이동하면 x−ct가 같은 점을 따라갑니다. 왼쪽 이동은 x+ct가 일정합니다. 이 두 characteristic coordinates(특성좌표)를 선택하면 진행 방향별 변화를 분리할 수 있습니다. 일반 함수 두 개가 나오는 적분은 다음 페이지에서 완성합니다.')
    ], [
      C('1 · 파동을 따라 움직이는 자를 놓습니다.', '오른쪽으로 c만큼씩 움직이는 봉우리의 처음 위치를 a라고 하면 t초 뒤 위치는 x=a+ct입니다. 정리하면 x−ct=a가 계속 같습니다. 왼쪽으로 움직이는 봉우리는 x+ct=a가 같습니다. 그래서 새 좌표를 v=x+ct, w=x−ct로 정합니다. 이름은 새로워도 “움직이는 모양 위에서 같은 점을 따라가는 번호”입니다.', M(r"v=x+ct,\quad w=x-ct,\qquad x=\frac{v+w}{2},\quad t=\frac{v-w}{2c}")),
      C('2 · 합성함수 미분을 두 갈래로 합니다.', 'u(x,t)를 새 좌표로 쓴 함수를 U(v,w)라 부릅니다. x를 조금 바꾸면 v,w가 둘 다 같은 양만큼 바뀝니다. t를 바꾸면 v는 c배로 늘고 w는 c배로 줄어듭니다. Chain rule(연쇄법칙)은 두 경로의 변화를 더하라는 규칙입니다.', M(r"\begin{aligned}u_x&=U_v\underbrace{v_x}_{1}+U_w\underbrace{w_x}_{1}=U_v+U_w,\\u_t&=U_v\underbrace{v_t}_{c}+U_w\underbrace{w_t}_{-c}=cU_v-cU_w.\end{aligned}")),
      C('3 · 다시 미분하면 가운데 항의 부호만 다릅니다.', M(r"\begin{aligned}u_{xx}&=(U_{vv}+U_{vw})+(U_{wv}+U_{ww})\\&=U_{vv}+2U_{vw}+U_{ww},\\u_{tt}&=c(cU_{vv}-cU_{vw})-c(cU_{wv}-cU_{ww})\\&=c^2U_{vv}-2c^2U_{vw}+c^2U_{ww}.\end{aligned}"), '매끄러운 함수에서는 Uᵥw=Uwᵥ입니다. 파동방정식의 왼쪽 uₜₜ−c²uₓₓ를 만들면 양 끝 항은 지워지고 가운데 항 −4c²Uᵥw만 남습니다.', M(r"u_{tt}-c^2u_{xx}=-4c^2U_{vw}=0\quad\Rightarrow\quad U_{vw}=0"), '무작정 새 변수를 도입한 것이 아니라, 복잡한 식을 “한 번씩 섞어 미분하면 0”이라는 간단한 식으로 바꾸려는 선택이었습니다. 경계조건과 초기조건은 아직 맞추지 않았습니다.')
    ])

    add(14, '일반해 · 왼쪽 진행파와 오른쪽 진행파의 합', [
      C('혼합미분 0을 두 번 적분합니다.', M(r"U_{vw}=0\quad\Rightarrow\quad U_v=H(v)\quad\Rightarrow\quad U(v,w)=\Phi(v)+\Psi(w)"), 'w로 미분한 Uᵥ가 0이므로 Uᵥ는 w에 의존하지 않습니다. v에 대해 적분하면 적분상수 역할에 임의함수 Ψ(w)가 남습니다.', M(r"\boxed{u(x,t)=\Phi(x+ct)+\Psi(x-ct)}")),
      C('진행 방향과 대입 검산', 'Φ(x+ct)는 왼쪽, Ψ(x−ct)는 오른쪽으로 속도 c로 이동합니다. 매끄러운 Φ,Ψ에 대해 uₜₜ=c²Φ″+c²Ψ″, uₓₓ=Φ″+Ψ″이므로 PDE를 만족합니다.', M(r"\begin{aligned}x+ct=a&\Rightarrow x=a-ct\quad\text{left-going},\\x-ct=a&\Rightarrow x=a+ct\quad\text{right-going}.\end{aligned}"), '이것은 파동방정식 자체의 일반해입니다. 임의의 Φ,Ψ를 고르면 원본의 u(0,t)=u(L,t)=0이 자동으로 성립하지 않습니다. 초기조건과 경계조건이 이 두 함수를 제한합니다.'),
      C('Standing wave(정상파)와 travelling wave(진행파)는 연결됩니다.', '편집자 연결: 한 공간 사인 모드를 곱-합 공식으로 바꾸면 좌우로 진행하는 같은 크기의 두 파동이 됩니다.', M(r"\sin(\kappa x)\cos(c\kappa t)=\frac12\sin[\kappa(x+ct)]+\frac12\sin[\kappa(x-ct)]"), '변수분리법과 D’Alembert 해법은 서로 다른 현상을 푸는 것이 아니라 같은 해를 다른 방식으로 표현합니다.')
    ], [
      C('1 · 미분해서 0이면 그 변수로는 변하지 않습니다.', 'Uᵥw=0은 “Uᵥ를 w로 미분했더니 0”입니다. 따라서 Uᵥ는 w에 따라 달라지지 않고 v만의 함수 H(v)입니다. 이것을 v로 적분하면 Φ(v)가 됩니다. 그런데 v로 미분할 때 사라지는 Ψ(w)도 자유롭게 더할 수 있습니다.', M(r"U_v=H(v)\quad\Rightarrow\quad U=\Phi(v)+\Psi(w)\quad\Rightarrow\quad u=\Phi(x+ct)+\Psi(x-ct)"), '적분상수가 함수가 된 이유는 4쪽의 A(y),B(y)와 같습니다. 지금 적분하는 변수 외의 변수는 고정한 숫자처럼 취급하기 때문입니다.'),
      C('2 · 괄호 안의 +가 오른쪽 이동이라는 뜻은 아닙니다.', 'Ψ(x−ct)의 봉우리가 처음 괄호값 0에 있었다면 시간이 지나도 x−ct=0인 곳에 봉우리가 있습니다. 즉 x=ct이므로 오른쪽으로 갑니다. Φ(x+ct)는 x=−ct인 곳으로 가므로 왼쪽입니다.', M(r"x-ct=0\Rightarrow x=ct,\qquad x+ct=0\Rightarrow x=-ct"), 'Travelling wave(진행파)는 모양을 유지하며 이동하는 파동입니다. 실제 줄의 한 점이 좌우로 달리는 것과는 다릅니다. 줄의 점은 위아래로 움직이고 변형의 모양이 전달됩니다.'),
      C('3 · 아까의 사인 진동도 두 진행파로 만들 수 있습니다.', M(r"\sin(\kappa x)\cos(c\kappa t)=\tfrac12\sin[\kappa(x+ct)]+\tfrac12\sin[\kappa(x-ct)]"), '좌우로 가는 파동을 더하면 특정 점은 늘 서로 상쇄되어 마디가 됩니다. 그래서 공간 모양이 고정된 standing wave(정상파)가 보입니다. 두 풀이 방법이 연결되는 이유입니다. 다만 Φ와 Ψ를 아무렇게나 고르면 끝점이 고정되지 않습니다. 이제 처음 모양과 속도를 먼저 맞추고, 이어서 끝점도 맞춥니다.')
    ])

    add(15, '초기변위와 초기속도로 Φ, Ψ를 정하는 과정', [
      C('두 초기조건을 합과 차의 식으로 바꿉니다.', M(r"\Phi(x)+\Psi(x)=f(x),\qquad c\Phi'(x)-c\Psi'(x)=g(x)"), '첫 식을 x로 미분하고 둘째 식을 c로 나누면 Φ′+Ψ′=f′, Φ′−Ψ′=g/c입니다.', M(r"\Phi'=\frac12f'+\frac1{2c}g,\qquad\Psi'=\frac12f'-\frac1{2c}g")),
      C('기준점 a에서 적분하고 적분상수를 맞춥니다.', M(r"\begin{aligned}\Phi(z)&=\frac12f(z)+\frac1{2c}\int_a^zg(s)\,ds+K,\\\Psi(z)&=\frac12f(z)-\frac1{2c}\int_a^zg(s)\,ds-K.\end{aligned}"), '두 식을 더했을 때 f가 되어야 하므로 상수는 서로 상쇄됩니다. 기준점 a는 임의이며 최종 해에서는 사라집니다. z,s는 각각 함수의 입력과 적분 안에서만 쓰는 dummy variable(더미 변수)입니다.'),
      C('x+ct와 x−ct를 넣으면 하나의 정적분이 남습니다.', M(r"\int_a^{x+ct}g(s)\,ds-\int_a^{x-ct}g(s)\,ds=\int_{x-ct}^{x+ct}g(s)\,ds"), M(r"u(x,t)=\frac{f(x+ct)+f(x-ct)}2+\frac1{2c}\int_{x-ct}^{x+ct}g(s)\,ds"), '초기속도 항의 부호와 1/(2c)는 합·차 연립식에서 결정됩니다. 아직 f,g가 어디까지 정의되어 있는지 확인해야 하므로, 유한 구간의 고정단 문제에는 다음 페이지의 연장을 함께 사용합니다.')
    ], [
      C('1 · 두 모르는 함수를 구하려면 두 정보가 필요합니다.', 'u=Φ(x+ct)+Ψ(x−ct)에 t=0을 넣으면 두 괄호가 모두 x입니다. 그래서 처음 모양은 Φ+Ψ입니다. 속도는 t로 미분해서 구합니다. 앞 괄호는 +c, 뒤 괄호는 −c가 나오므로 속도는 cΦ′−cΨ′입니다.', M(r"\Phi+\Psi=f,\qquad c\Phi'-c\Psi'=g")),
      C('2 · 더하기와 빼기로 푸는 연립방정식입니다.', '첫 식을 x로 미분하면 Φ′+Ψ′=f′입니다. 둘째 식을 c로 나누면 Φ′−Ψ′=g/c입니다. 두 식을 더하면 Ψ′가 사라지고, 빼면 Φ′가 사라집니다.', M(r"\begin{aligned}\Phi'+\Psi'&=f',\qquad\Phi'-\Psi'=g/c,\\2\Phi'&=f'+g/c,\qquad 2\Psi'=f'-g/c.\end{aligned}"), '어려운 새 원리가 아니라 고등학교 연립방정식의 소거법입니다. 미지수가 숫자 대신 함수의 미분값일 뿐입니다.'),
      C('3 · 미분을 되돌리면 속도의 적분이 나타납니다.', M(r"\Phi(z)=\frac{f(z)}2+\frac1{2c}\int_a^zg(s)\,ds+K,\qquad\Psi(z)=\frac{f(z)}2-\frac1{2c}\int_a^zg(s)\,ds-K"), 'f′를 적분하면 f이고, g는 어떤 함수인지 모르니 정적분으로 남깁니다. 두 상수를 K와 −K로 쓴 것은 Φ+Ψ가 정확히 f가 되게 하려는 것입니다. s는 적분 안에서 돌아다니는 임시 변수입니다.'),
      C('4 · 두 누적량의 차이는 그 사이 구간의 양입니다.', '처음 함수 Φ에는 x+ct를, Ψ에는 x−ct를 넣습니다. 속도의 적분은 a부터 오른쪽 끝까지 누적한 양에서 a부터 왼쪽 끝까지 누적한 양을 뺀 꼴이 됩니다. 겹치는 구간이 사라져 두 끝점 사이의 적분만 남습니다.', M(r"u(x,t)=\frac12[f(x+ct)+f(x-ct)]+\frac1{2c}\int_{x-ct}^{x+ct}g(s)\,ds"), '이것이 D’Alembert formula(달랑베르 공식)입니다. 공식에 x−ct가 음수로 나올 수 있다는 점을 그냥 넘기면 안 됩니다. 길이가 유한한 줄에서는 밖의 함수값을 정하는 방법까지 알아야 합니다.')
    ])

    add(16, 'D’Alembert 공식 · 고정단에 필요한 홀수 주기 연장', [
      C('전체 직선 위의 초기값 문제에 대한 공식', M(r"\boxed{u(x,t)=\frac12[f(x+ct)+f(x-ct)]+\frac1{2c}\int_{x-ct}^{x+ct}g(s)\,ds}"), '충분히 매끄럽고 실수 전체에 주어진 f,g에 대한 해입니다. t=0을 넣으면 적분구간 길이가 0이므로 u(x,0)=f(x)입니다. Leibniz rule(라이프니츠 적분 미분법)로 시간 미분하면 다음과 같아 초기속도도 확인됩니다.', M(r"u_t=\frac c2[f'(x+ct)-f'(x-ct)]+\frac12[g(x+ct)+g(x-ct)]\quad\Rightarrow\quad u_t(x,0)=g(x)")),
      C('원본의 0≤x≤L 고정단 문제에서는 연장 조건을 보강합니다.', 'f,g가 [0,L]에만 정의되어 있으면 x±ct가 구간 밖으로 나갔을 때 원래 식만으로는 계산할 수 없습니다. 각각을 odd 2L-periodic extension(홀수 2L-주기 연장)한 f̃,g̃를 위 공식에 넣습니다. 이는 원본 공식을 바꾸는 교정이 아니라 생략된 적용 조건의 보강입니다.', M(r"\widetilde f(x)=f(x)\ (0\le x\le L),\quad\widetilde f(-x)=-\widetilde f(x),\quad\widetilde f(x+2L)=\widetilde f(x)"), 'g도 같은 방식으로 연장합니다. 연속적인 고정단 데이터에는 끝점 값이 0이어야 합니다. 이 연장은 x=L 주위에서도 f̃(L+s)=−f̃(L−s), g̃(L+s)=−g̃(L−s)를 만족합니다.'),
      C('왜 양 끝의 높이가 계속 0이 되는가?', 'x=0에서 초기변위 두 항은 홀대칭으로 상쇄되고, 초기속도의 적분도 대칭 구간에서 홀함수를 적분하므로 0입니다. x=L에서도 L 주위의 홀대칭 때문에 같은 일이 일어납니다.', M(r"\begin{aligned}u(0,t)&=\tfrac12[\widetilde f(ct)+\widetilde f(-ct)]+\tfrac1{2c}\int_{-ct}^{ct}\widetilde g(s)\,ds=0,\\u(L,t)&=\tfrac12[\widetilde f(L+ct)+\widetilde f(L-ct)]+\tfrac1{2c}\int_{L-ct}^{L+ct}\widetilde g(s)\,ds=0.\end{aligned}"), '이 부호 반전은 fixed-end reflection(고정단 반사)을 표현합니다. 끝점 조건을 적용하지 않은 전체 직선 공식과 구분해야 합니다.'),
      C('영향 구간과 간단한 점검 예제', '전체 직선에서는 (x,t)의 값이 [x−ct,x+ct] 안의 초기데이터에만 의존합니다. 이를 domain of dependence(의존영역)라 부릅니다. 유한 줄에서는 연장된 값을 통해 끝에서 반사된 영향도 포함합니다.', '편집자 검산: 고정단 문제가 아닌 전체 직선에서 f=0, g=v₀가 상수이면 적분은 2ctv₀이므로 u=v₀t입니다. 초기속도 항의 1/(2c)가 맞는지 빠르게 확인할 수 있습니다.')
    ], [
      C('1 · 모양 두 개의 평균에 처음 밀어 준 효과를 더합니다.', M(r"u(x,t)=\frac{f(x+ct)+f(x-ct)}2+\frac1{2c}\int_{x-ct}^{x+ct}g(s)\,ds"), '첫 부분은 처음 모양의 절반씩을 좌우로 이동시켜 더한 것입니다. g=0이면 여기서 끝납니다. 두 번째 부분은 속도 g가 만드는 추가 변위입니다. x−ct부터 x+ct 사이에서 처음에 어떻게 밀었는지가 적분되어 현재 높이에 기여합니다.'),
      C('2 · t=0을 넣어 공식이 조건을 지키는지 확인합니다.', '첫 부분은 [f(x)+f(x)]/2=f(x)이고, 적분은 x부터 x까지이므로 0입니다. 속도를 확인할 때는 적분의 오른쪽 끝이 c의 속도로 늘고 왼쪽 끝이 −c의 속도로 줄어드는 효과를 함께 셉니다.', M(r"\frac{d}{dt}\int_{x-ct}^{x+ct}g(s)\,ds=cg(x+ct)+cg(x-ct)"), M(r"u_t=\frac c2[f'(x+ct)-f'(x-ct)]+\frac12[g(x+ct)+g(x-ct)]"), 't=0이면 f′ 두 개는 상쇄되고 g 두 개의 평균이 g입니다. 따라서 처음 모양뿐 아니라 처음 속도도 맞습니다.'),
      C('3 · 음수 위치의 f는 어디서 가져오나요?', '편집자 예로 L=1, c=1, x=0.2, t=0.5이면 x−ct=−0.3입니다. 그런데 줄은 0부터 1까지만 주어졌습니다. 그냥 f(−0.3)를 계산할 근거는 없습니다. 끝점이 고정되도록 바깥을 연결해야 합니다. 먼저 왼쪽에는 높이를 뒤집어 f̃(−x)=−f(x)로 놓습니다.', M(r"\widetilde f(-0.3)=-f(0.3)\qquad(L=1)"), '이것이 odd extension(홀연장)입니다. 원래 함수가 정의되지 않은 곳의 값을 새로 정의하는 것이지, 원래 f가 처음부터 홀함수였다고 주장하는 것이 아닙니다.'),
      C('4 · 오른쪽 끝에서도 뒤집고, 길이 2L마다 반복합니다.', '음의 구간까지 만든 모양을 2L마다 반복하면 x=L 주위에서도 부호가 반대로 연결됩니다. 예를 들어 L=1에서 f̃(1.2)=−f(0.8)입니다. 같은 작업을 초기속도 g에도 합니다.', M(r"\widetilde f(x+2L)=\widetilde f(x),\qquad\widetilde f(L+s)=-\widetilde f(L-s)"), '이제 공식의 f,g 자리에 f̃,g̃를 넣습니다. x=0에서 좌우 두 높이는 +와 −로 상쇄되고 속도 적분도 상쇄됩니다. x=L에서도 같습니다. 그래서 줄의 양 끝이 계속 0입니다. Fixed-end reflection(고정단 반사)에서 파동이 뒤집히는 모습이 이 연장에 들어 있습니다.'),
      C('5 · 어느 부분의 처음 상태가 영향을 주나요?', '현재 위치 x에서 왼쪽 x−ct, 오른쪽 x+ct까지가 공식에 등장합니다. 파동이 시간 t 동안 거리 ct만큼 전달되기 때문입니다. 이것이 domain of dependence(의존영역)입니다. 유한 줄의 바깥 좌표는 실제 다른 줄이 아니라 반사 계산용 복사본으로 이해하면 됩니다.', '편집자 검산으로 무한히 긴 줄에서 f=0, g=v₀라면 적분은 “폭 2ct × 높이 v₀”입니다. 2c로 나누면 v₀t, 즉 일정한 속도로 움직인 거리입니다. 이 예제에는 고정된 끝점이 없다는 조건을 함께 기억하십시오.')
    ])

    add(17, '2차 PDE의 분류 · B² − AC의 의미', [
      C('최고차 미분항의 계수를 먼저 읽습니다.', M(r"A u_{xx}+2B u_{xy}+C u_{yy}=F(x,y,u,u_x,u_y),\qquad\Delta=B^2-AC"), 'Principal part(주부분)는 최고차인 2차 미분항들입니다. Quasilinear(준선형)는 최고차 도함수에 대해 선형이라는 뜻이며, 식 전체가 선형이라는 뜻은 아닙니다. A,B,C가 x,y만의 함수이고 낮은 차수 항이 비선형이면 더 좁게 semilinear(반선형)라고 부릅니다. 계수가 u나 1차 도함수에도 의존할 수 있는 경우까지 준선형에 포함합니다.'),
      C('판별식과 대표 방정식', table(['Δ의 부호','유형','대표식과 계수'], [('Δ&gt;0','Hyperbolic(쌍곡형)','c²uₓₓ−uₜₜ=0: (A,B,C)=(c²,0,−1), Δ=c²'),('Δ=0','Parabolic(포물형)','c²uₓₓ−uₜ=0: (A,B,C)=(c²,0,0), Δ=0'),('Δ&lt;0','Elliptic(타원형)','uₓₓ+uᵧᵧ=f: (A,B,C)=(1,0,1), Δ=−1')]), '위 표에서 시간식은 두 번째 독립변수를 y=t로 읽었습니다. c&gt;0을 가정합니다. A=B=C=0인 지점은 2차 주부분이 사라지므로 단순히 “Δ=0이라 포물형”으로 분류하지 않습니다. 변수계수에서는 위치에 따라 유형이 달라질 수 있습니다.'),
      C('혼합항 앞에는 2B가 있습니다 · 편집자 추가 예제', M(r"u_{xx}+4u_{xy}+u_{yy}=0\quad\Rightarrow\quad A=1,\ B=2,\ C=1,\ \Delta=4-1=3>0"), 'uₓᵧ의 계수 4를 B로 그대로 쓰면 안 됩니다. 또 uₓₓ+y uᵧᵧ=0은 Δ=−y이므로 y&gt;0에서 타원형, y&lt;0에서 쌍곡형, y=0에서는 주부분이 0이 아닌 퇴화한 포물형 지점입니다. 초기·경계값 문제의 전체 성질은 낮은 차수 항과 영역도 함께 살펴야 합니다.')
    ], [
      C('1 · 일단 가장 많이 미분한 항만 모읍니다.', 'PDE의 풀이 방식은 최고차 미분항의 조합에 크게 좌우됩니다. 2차 PDE라면 uₓₓ,uₓᵧ,uᵧᵧ를 모으고 그 앞의 수를 읽습니다. 원본은 가운데 계수를 2B로 쓰므로 절반이 B입니다.', M(r"A u_{xx}+2B u_{xy}+C u_{yy}=F,\qquad \Delta=B^2-AC"), '예를 들어 uₓₓ+4uₓᵧ+uᵧᵧ=0이면 A=1,B=2,C=1이고 Δ=3입니다. 이 예제는 계수 읽기 연습을 위한 편집자 보강입니다.'),
      C('2 · 고등학교 이차방정식의 판별식과 연결됩니다.', '다음 페이지에서 파동 정보가 이동하는 방향의 기울기를 m이라 쓰면 Am²−2Bm+C=0이 나옵니다. 그 판별식은 (−2B)²−4AC=4(B²−AC)입니다. 4는 양수이므로 부호를 정하는 것은 Δ입니다.', M(r"m=\frac{B\pm\sqrt{B^2-AC}}{A}\qquad(A\ne0)"), '양수이면 서로 다른 두 실수 방향이 있어 hyperbolic(쌍곡형), 0이면 겹치는 방향으로 parabolic(포물형), 음수이면 실수 방향이 없어 elliptic(타원형)이라고 부릅니다. 이름을 외우기 전에 “방향을 찾는 이차방정식의 실근 개수”를 연결하십시오.'),
      C('3 · 익숙한 세 식에서 직접 셉니다.', M(r"\begin{array}{c|c|c}\text{식}&(A,B,C)&\Delta\\\hline c^2u_{xx}-u_{tt}=0&(c^2,0,-1)&c^2>0\\c^2u_{xx}-u_t=0&(c^2,0,0)&0\\u_{xx}+u_{yy}=0&(1,0,1)&-1<0\end{array}"), '첫 두 식에서는 y 자리에 t를 썼다고 생각합니다. 확산식의 uₜ는 1차 미분이므로 C가 아닙니다. C는 uₜₜ 앞의 계수이며 그런 항이 없으니 0입니다. Poisson equation(푸아송 방정식)도 오른쪽 원천항만 달라져 타원형입니다.'),
      C('4 · 준선형은 “전부 선형”보다 약한 조건입니다.', 'Quasilinear(준선형)는 가장 높은 미분들끼리 곱하거나 제곱하지 않는다는 뜻입니다. 낮은 차수 부분에는 u² 같은 비선형 항이 있어도 됩니다. 반면 linear(선형)는 u와 모든 도함수 전체에 선형이어야 합니다.', 'A,B,C가 위치에 따라 달라지면 Δ도 위치에 따라 달라집니다. 예를 들어 uₓₓ+y uᵧᵧ=0은 Δ=−y이므로 위쪽 y&gt;0과 아래쪽 y&lt;0에서 유형이 다릅니다. A,B,C가 모두 0인 점에서는 2차 항이 아예 사라지므로 세 분류표를 그대로 적용하지 않습니다.')
    ])

    add(19, 'Characteristic curves(특성곡선) · 왜 x ± ct인가?', [
      C('특성방정식과 실근의 수', M(r"A\left(\frac{dy}{dx}\right)^2-2B\frac{dy}{dx}+C=0,\qquad\frac{dy}{dx}=\frac{B\pm\sqrt{B^2-AC}}{A}\quad(A\ne0)"), 'Characteristic curve(특성곡선)는 최고차 미분 구조가 특정 방향으로 퇴화하는 곡선입니다. 쌍곡형 파동에서는 정보와 불연속이 전파되는 방향으로 해석합니다. 타원형에는 실수 특성곡선이 없으므로 모든 PDE에서 유한속도의 전파 경로가 있다는 뜻은 아닙니다.'),
      C('편집자 유도 · 곡선이 좌표가 될 때 사라지는 계수', '곡선을 ξ(x,y)=상수로 놓고 새 좌표로 미분하면 Uξξ 앞의 계수는 Aξₓ²+2Bξₓξᵧ+Cξᵧ²입니다. 이 계수가 0이 되는 방향을 찾습니다. 곡선을 따라 dξ=ξₓdx+ξᵧdy=0이므로 ξₓ=−y′ξᵧ입니다.', M(r"A\xi_x^2+2B\xi_x\xi_y+C\xi_y^2=(\xi_y)^2[A(y')^2-2By'+C]=0"), 'ξᵧ≠0인 국소 구간에서 원본의 식을 얻습니다. 수직 접선이나 A=0에서는 나눗셈 형태 대신 A(dy)²−2Bdxdy+C(dx)²=0을 사용해 빠지는 방향이 없는지 확인합니다.'),
      C('파동방정식에 적용하면 이동 좌표가 다시 나옵니다.', 'y=t로 놓고 c²uₓₓ−uₜₜ=0에서 A=c²,B=0,C=−1을 읽습니다.', M(r"c^2\left(\frac{dt}{dx}\right)^2-1=0\quad\Rightarrow\quad\frac{dt}{dx}=\pm\frac1c\quad\Rightarrow\quad t=\pm\frac xc+K"), M(r"x-ct=\text{constant}\qquad\text{or}\qquad x+ct=\text{constant}"), '13쪽의 변수변환은 바로 이 두 특성곡선족을 좌표로 택한 것입니다. x를 가로축, t를 세로축으로 그리면 기울기는 ±1/c이고, 실제 공간 이동 속도 dx/dt는 ±c입니다.'),
      C('편집자 추가 예제 · 혼합미분항이 있는 경우', M(r"u_{xx}+4u_{xy}+u_{yy}=0\quad\Rightarrow\quad (y')^2-4y'+1=0\quad\Rightarrow\quad y=(2\pm\sqrt3)x+K"), 'B=2임을 먼저 확인했습니다. 계수가 상수인 이 예제의 특성곡선은 직선입니다. 변수계수이면 y′가 위치에 의존할 수 있어 추가 미분방정식을 풀어 곡선을 구합니다.')
    ], [
      C('1 · 어떤 방향으로 움직이면 같은 파동을 따라가나요?', '오른쪽 진행파 Ψ(x−ct)를 따라가려면 x−ct가 일정해야 했습니다. 이렇게 파동 정보의 이동 방향을 보여 주는 곡선을 characteristic curve(특성곡선)라 합니다. 곡선이 항상 직선인 것은 아니지만 이 단원의 일정 속도 파동에서는 직선입니다.'),
      C('2 · 기울기 m에 대한 이차방정식을 풉니다.', M(r"m=\frac{dy}{dx},\qquad Am^2-2Bm+C=0\quad\Rightarrow\quad m=\frac{B\pm\sqrt{B^2-AC}}A\quad(A\ne0)"), '고등학교 근의 공식 그대로입니다. A,B,C를 원래 PDE에서 읽고, 기울기를 구한 뒤 곡선을 적분해서 찾습니다. Δ&gt;0이면 두 방향, Δ=0이면 겹친 방향, Δ&lt;0이면 실수 방향이 없다는 앞 페이지의 분류가 여기서 나옵니다.'),
      C('3 · 파동방정식에서는 y 대신 시간을 씁니다.', M(r"c^2u_{xx}-u_{tt}=0\quad\Rightarrow\quad A=c^2,\ B=0,\ C=-1"), M(r"c^2m^2-1=0\quad\Rightarrow\quad m=\pm1/c\quad\Rightarrow\quad t=\pm x/c+K"), '세로축이 t이므로 m은 dt/dx입니다. 직선식의 항을 옮기면 x−ct=상수 또는 x+ct=상수가 됩니다. 즉 D’Alembert 해법에서 쓴 두 좌표가 나온 것입니다. 기울기 ±1/c와 속도 ±c를 서로 바꾸어 읽지 마십시오.'),
      C('4 · 식의 부호는 어디서 왔을까요? · 편집자 보강', '곡선 위에서 일정한 번호를 ξ(x,y)라 쓰면, 곡선을 따라 움직일 때 변화가 0이므로 ξₓ+ξᵧy′=0입니다. 따라서 ξₓ=−ξᵧy′가 되어 음수가 생깁니다. 새 좌표의 두 번 미분항 앞 계수에 넣으면 다음처럼 됩니다.', M(r"A\xi_x^2+2B\xi_x\xi_y+C\xi_y^2=(\xi_y)^2[A(y')^2-2By'+C]"), '대괄호가 0인 방향에서는 그 방향의 최고차 미분항이 사라져 식이 단순해집니다. 이 단락의 유도는 용어 뒤의 이유를 보여 주는 보강입니다. 당장 문제에서는 계수 읽기 → 기울기 방정식 → 곡선 찾기 순서로 계산하면 됩니다.'),
      C('5 · 혼합항 예제를 끝까지 풀어봅니다.', '편집자 예제 uₓₓ+4uₓᵧ+uᵧᵧ=0에서는 B=4가 아니라 2입니다.', M(r"m^2-4m+1=0\Rightarrow m=2\pm\sqrt3\Rightarrow y=(2\pm\sqrt3)x+K"), '수직선은 dy/dx로 나타낼 수 없고 A=0이면 근의 공식에서 A로 나눌 수 없습니다. 그때는 A(dy)²−2Bdxdy+C(dx)²=0으로 돌아갑니다. 또한 타원형 PDE에는 이런 실수 특성 경로가 없으므로 “모든 PDE의 정보는 이 길로 흐른다”로 확대하지 않습니다.')
    ])
